    "K": 13,
    "A": 14,
}

HIGH_CARD = 0
PAIR = 1
TWO_PAIR = 2
THREE_OF_A_KIND = 3
STRAIGHT = 4
FLUSH = 5
FULL_HOUSE = 6
FOUR_OF_A_KIND = 7
STRAIGHT_FLUSH = 8


def _rank_card(card):
    """Return the numeric rank of a card like '10H' or 'AC'."""
    rank, suit = card[:-1], card[-1]
    return RANKS[rank], suit


def _score_hand(hand):
    """Return a comparable score tuple for a hand string."""
    cards = hand.split()
    values = sorted((_rank_card(card)[0] for card in cards), reverse=True)
    suits = [card[-1] for card in cards]
    counts = {value: values.count(value) for value in values}
    # Ranks ordered by count (descending), then by rank (descending).
    by_count = sorted(counts, key=lambda v: (counts[v], v), reverse=True)
    is_flush = len(set(suits)) == 1
    is_straight = values[0] - values[4] == 4 and len(set(values)) == 5

    if is_straight and is_flush:
        top = values[0]
        if top == 14 and values[1] == 5:  # A-2-3-4-5, ace plays low
            top = 5
        return (STRAIGHT_FLUSH, top)
    if is_flush:
        return (FLUSH, *values)
    if is_straight:
        top = values[0]
        if top == 14 and values[1] == 5:  # A-2-3-4-5, ace plays low
            top = 5
        return (STRAIGHT, top)
    if counts[by_count[0]] == 4:
        return (FOUR_OF_A_KIND, by_count[0], by_count[1])
    if counts[by_count[0]] == 3 and counts[by_count[1]] == 2:
        return (FULL_HOUSE, by_count[0], by_count[1])
    if counts[by_count[0]] == 3:
        return (THREE_OF_A_KIND, by_count[0], *sorted(counts, key=lambda v: (counts[v], v)))
    if counts[by_count[0]] == 2 and counts[by_count[1]] == 2:
        return (TWO_PAIR, by_count[0], by_count[1], by_count[2])
    if counts[by_count[0]] == 2:
        return (PAIR, by_count[0], *sorted(counts, key=lambda v: (counts[v], v)))
    return (HIGH_CARD, *values)


def best_hands(hands):
    """Return the hand(s) with the highest score, in input order."""
    scores = [(score, hand) for hand in hands for score in [_score_hand(hand)]]
    top = max(score for score, _ in scores)
    return [hand for score, hand in scores if score == top]

