        return (STRAIGHT, straight_top)

    counts = {value: values.count(value) for value in values}
    if counts[values[0]] == 4 or len(counts) == 2:
        # Four of a kind or full house; the descending values already
        # put the triplet/quad ranks first, then the pair/kicker.
        category = FULL_HOUSE if len(counts) == 2 else FOUR_OF_A_KIND
        return (category, *values)
