        # Two pair or three of a kind; values are ordered high to low.
        category = TWO_PAIR if counts[values[0]] == 2 else THREE_OF_A_KIND
        return (category, *values)
    if len(counts) == 4:
        return (PAIR, *values)
    return (HIGH_CARD, *values)


def best_hands(hands):
    """Return the hand(s) with the highest score, in input order."""
    scored = [(_score_hand(hand), hand) for hand in hands]
    top = max(score for score, _ in scored)
